<?php declare(strict_types=1); namespace Annam; $title=$category?$category['name'].' items':'Dishes & products'; $link=fn($changes)=>'?'.http_build_query(array_replace($_GET,$changes,['page'=>1])); $context=['kind'=>$kind,'return_url'=>$return_url];if($slot&&$date)$context+=['date'=>$date,'slot_id'=>$slot['id']]; ?>
<div class="o-actions"><a class="o-btn o-btn-primary" href="<?= e($base.'new/?'.http_build_query($context)) ?>">+ Add item</a><?php if(!$category): foreach(['scheduled'=>'Meals','courier'=>'Other items'] as $k=>$v): ?><a class="o-btn <?= $kind===$k?'o-btn-primary':'' ?>" href="<?= e($link(['kind'=>$k,'meal'=>''])) ?>"><?= e($v) ?></a><?php endforeach; endif; ?></div>
<?php if(!$category&&$kind==='scheduled'): ?><div class="o-actions"><?php foreach(['breakfast','lunch','dinner','snacks','unassigned'] as $k): ?><a class="o-btn <?= $meal===$k?'o-btn-primary':'' ?>" href="<?= e($link(['meal'=>$k])) ?>"><?= e(ucfirst($k)) ?></a><?php endforeach; ?></div><?php if($slot): ?><div class="o-actions"><?php foreach([date('Y-m-d')=>'Today',date('Y-m-d',strtotime('+1 day'))=>'Tomorrow','all'=>'All dishes'] as $d=>$v): ?><a class="o-btn <?= ($date??'all')===$d?'o-btn-primary':'' ?>" href="<?= e($link(['date'=>$d])) ?>"><?= e($v) ?></a><?php endforeach; ?><a class="o-btn" href="/manage/dishes/menu/?date=<?= e($date??date('Y-m-d')) ?>&slot_id=<?= e($slot['id']) ?>">Choose dishes for this date</a></div><?php endif; endif; ?>
<?php if($category): ?><div class="o-actions"><a class="o-btn" href="<?= e($link(['status'=>'1','stock'=>'1'])) ?>">On website</a><a class="o-btn" href="<?= e($link(['status'=>'','stock'=>''])) ?>">All items including hidden</a></div><?php endif; ?><form class="o-filters"><input type="hidden" name="status" value="<?= e($_GET['status']??'') ?>"><input type="hidden" name="kind" value="<?= e($kind) ?>"><input type="hidden" name="meal" value="<?= e($meal) ?>"><input type="hidden" name="date" value="<?= e($date??'all') ?>"><input name="q" value="<?= e($query) ?>" placeholder="Search items"><select name="stock"><option value="">All stock</option><option value="1" <?= ($_GET['stock']??'')==='1'?'selected':'' ?>>In stock</option><option value="0" <?= ($_GET['stock']??'')==='0'?'selected':'' ?>>Sold out</option></select><button class="o-btn">Search</button></form><p><?= e($total) ?> items<?= $slot&&$date?' · '.e($date).' · '.e($slot['label']):'' ?></p>
<div class="o-table-wrap"><table class="o-table"><thead><tr><th>Item</th><th>Category</th><th>Price</th><th>On sale</th><th>Stock</th><th>Actions</th></tr></thead><tbody><?php foreach($records as $r): ?><tr><td><strong><?= e($r['name']) ?></strong><?php if($r['weight']): ?><small><?= e($r['weight']) ?></small><?php endif; ?></td><td><?= e($r['category_name']??'') ?></td><td><?= money($r['effective_price']??$r['price']) ?></td><td><form method="post" action="<?= e($base.$r['id'].'/toggle/') ?>"><?= csrf() ?><input type="hidden" name="return_url" value="<?= e($return_url) ?>"><?php if($slot&&$date): ?><input type="hidden" name="menu_date" value="<?= e($date) ?>"><input type="hidden" name="menu_slot_id" value="<?= e($slot['id']) ?>"><input type="hidden" name="revision" value="<?= e($revision) ?>"><input type="hidden" name="available" value="<?= empty($r['available'])?'1':'' ?>"><?php endif; ?><label class="o-check"><input type="checkbox" role="switch" data-submit-change aria-label="On sale: <?= e($r['name']) ?>" <?= ($slot&&$date?$r['available']:$r['active'])?'checked':'' ?>><span class="o-switch-ui" aria-hidden="true"><i></i></span><span><?= ($slot&&$date?$r['available']:$r['active'])?'On':'Off' ?></span></label><noscript><button class="o-btn">Change</button></noscript></form></td><td><form method="post" action="<?= e($base.$r['id'].'/stock/') ?>"><?= csrf() ?><input type="hidden" name="return_url" value="<?= e($return_url) ?>"><label class="o-check"><input type="checkbox" role="switch" data-submit-change aria-label="In stock: <?= e($r['name']) ?>" <?= $r['in_stock']?'checked':'' ?>><span class="o-switch-ui" aria-hidden="true"><i></i></span><span><?= $r['in_stock']?'In stock':'Sold out' ?></span></label><noscript><button class="o-btn">Change</button></noscript></form></td><td><a class="o-btn" href="<?= e($base.$r['id'].'/?'.http_build_query($context)) ?>">Edit</a><form method="post" action="<?= e($base.$r['id'].'/archive/') ?>"><?= csrf() ?><input type="hidden" name="return_url" value="<?= e($return_url) ?>"><?php if($slot&&$date): ?><input type="hidden" name="menu_date" value="<?= e($date) ?>"><input type="hidden" name="menu_slot_id" value="<?= e($slot['id']) ?>"><input type="hidden" name="revision" value="<?= e($revision) ?>"><?php endif; ?><button class="o-btn"><?= $slot&&$date?'Remove from this date':'Remove from sale' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div><div class="o-actions"><?php foreach(array_unique(array_filter([1,$page-1,$page,$page+1,(int)ceil($total/30)],fn($n)=>$n>=1&&$n<=max(1,ceil($total/30)))) as $n): ?><a class="o-btn <?= $page===$n?'o-btn-primary':'' ?>" href="<?= e('?'.http_build_query(array_replace($_GET,['page'=>$n]))) ?>"><?= $n ?></a><?php endforeach; ?></div><script src="/assets/admin-controls.js" defer></script>